const digits = String($json.telefone || '').replace(/\D/g, '');
const telefone = digits.startsWith('55') ? digits : (digits ? '55' + digits : '');

return {
  json: {
    nome: $json.nome || '',
    email: $json.email || '',
    telefone,
    origem: 'importacao_planilha',
    ref: '',
    row_number: $json.row_number,
    status_lote: $json.status || '',
    lead_id: $json.lead_id || '',
    erro_detalhe_anterior: $json.erro_detalhe || '',
    tentativas_reenvio: Number($json.tentativas_reenvio || 0) || 0,
    // Preco personalizado (colunas J/K/L da aba leads_importados) - pass-through, usado pela Geracao de Proposta via lead_id
    preco_personalizado: $json.preco_personalizado || '',
    valor_adesao_personalizado: $json.valor_adesao_personalizado || '',
    valor_mensalidade_personalizado: $json.valor_mensalidade_personalizado || '',
    data_importacao: DateTime.now().setZone('America/Sao_Paulo').toFormat('dd/MM/yyyy HH:mm')
  }
};

// ===== Limite diario de leads (cota de e-mails do Resend) =====
const LIMITE_DIARIO = 80;   // leads processados por dia (novos + reenvios). Ajuste aqui.
const TZ = 'America/Sao_Paulo';
const hoje = DateTime.now().setZone(TZ).startOf('day');
const fmt = dt => dt.toFormat('dd/MM/yyyy');
const parse = s => { const m = String(s || '').trim().match(/^(\d{2})\/(\d{2})\/(\d{4})/); return m ? DateTime.fromObject({ day: +m[1], month: +m[2], year: +m[3] }, { zone: TZ }) : null; };
const rows = $input.all().map(i => i.json);

// ja processados hoje (status sucesso com data_importacao de hoje) consomem o orcamento
const processadosHoje = rows.filter(r => r.status === 'sucesso' && String(r.data_importacao || '').startsWith(fmt(hoje))).length;
const orcamento = Math.max(0, LIMITE_DIARIO - processadosHoje);

// elegiveis hoje: novo, ou agendado/reenvio_email com agendado_para <= hoje (ou vazio)
const prio = r => (r.status === 'reenvio_email' ? 0 : r.status === 'agendado' ? 1 : 2);
const pend = rows.filter(r => ['novo', 'agendado', 'reenvio_email'].includes(r.status));
const elegiveis = pend.filter(r => { const d = parse(r.agendado_para); return r.status === 'novo' || !d || d <= hoje; })
  .sort((a, b) => (prio(a) - prio(b)) || ((parse(a.agendado_para) || hoje).toMillis() - (parse(b.agendado_para) || hoje).toMillis()) || (a.row_number - b.row_number));
const selecionados = elegiveis.slice(0, orcamento);
const selIds = new Set(selecionados.map(r => r.row_number));

// fila: tudo que ficou de fora e recebe uma data a partir de amanha, LIMITE_DIARIO por dia
const fila = pend.filter(r => !selIds.has(r.row_number))
  .sort((a, b) => (prio(a) - prio(b)) || ((parse(a.agendado_para) || DateTime.fromMillis(8.64e15)).toMillis() - (parse(b.agendado_para) || DateTime.fromMillis(8.64e15)).toMillis()) || (a.row_number - b.row_number));
const iS = 'status', colStatus = 'E', colAgend = 'N';  // colunas fixas da aba leads_importados
const data = []; const agenda = {};
let dia = hoje.plus({ days: 1 }), usados = 0;
for (const r of fila) {
  if (usados >= LIMITE_DIARIO) { dia = dia.plus({ days: 1 }); usados = 0; }
  const alvo = fmt(dia); usados++;
  const novoStatus = r.status === 'novo' ? 'agendado' : r.status;
  if (r.status !== novoStatus) data.push({ range: `leads_importados!${colStatus}${r.row_number}`, values: [[novoStatus]] });
  if (String(r.agendado_para || '') !== alvo) data.push({ range: `leads_importados!${colAgend}${r.row_number}`, values: [[alvo]] });
  agenda[alvo] = (agenda[alvo] || 0) + 1;
}
return [{ json: { hoje: fmt(hoje), limite_diario: LIMITE_DIARIO, processados_hoje: processadosHoje, orcamento, elegiveis: elegiveis.length, selecionados_qtd: selecionados.length, fila_qtd: fila.length, agenda, celulas_a_gravar: data.length, selecionados, data } }];

// Resultado do reenvio de boas-vindas + limite de tentativas
const MAX_TENTATIVAS = 3;
const TZ = 'America/Sao_Paulo';
const res = $input.first().json || {};
const lead = $('04_normaliza_lead_lote').first().json;
const enviado = res.enviado === true;
const tentativasAntes = Number(lead.tentativas_reenvio || 0) || 0;
const tentativas = enviado ? tentativasAntes : tentativasAntes + 1;
const escalar = !enviado && tentativas >= MAX_TENTATIVAS;
const agora = DateTime.now().setZone(TZ);
const status = enviado ? 'sucesso' : (escalar ? 'revisao_manual_email' : 'reenvio_email');
const erro = String(res.erro || 'falha no envio');
const erro_detalhe = enviado
  ? 'email_boasvindas_reenviado_em ' + agora.toFormat('dd/MM/yyyy HH:mm')
  : (escalar ? `revisao_manual_email: ${tentativas} tentativas falharam. Ultimo erro: ${erro}` : `email_boasvindas_nao_enviado (tentativa ${tentativas}/${MAX_TENTATIVAS}): ${erro}`);
return [{ json: {
  row_number: lead.row_number, nome: lead.nome, email: lead.email, lead_id: lead.lead_id,
  enviado, escalar, tentativas, status, erro, erro_detalhe,
  agendado_para: (enviado || escalar) ? '' : agora.plus({ days: 1 }).toFormat('dd/MM/yyyy'),
  data_importacao: enviado ? agora.toFormat('dd/MM/yyyy HH:mm') : lead.data_importacao,
  linha_planilha: lead.row_number
} }];

